che automatisch. Aktiviere die UI-Einstellungen zum Anordnen oder kehre zur Standardoberfläche zurück.\",\n [\"Slim Suite version:\"] = \"Slim-Suite-Version:\",\n [\"Slim Suite's gear button\"] = \"Slim Suites Zahnradtaste\",\n [\"Slim nameplates\"] = \"Schlanke Namensplaketten\",\n [\"Slim nameplates: slim health bar with the name above\"] = \"Schlanke Namensplaketten: schmale Lebensleiste mit dem Namen darüber\",\n [\"Smaller\"] = \"Kleiner\",\n [\"Snap nearby frames together\"] = \"Benachbarte Fenster einrasten\",\n [\"Snap to Elements\"] = \"An Elementen einrasten\",\n [\"Sound Effects\"] = \"Soundeffekte\",\n [\"Space between players\"] = \"Abstand zwischen Spielern\",\n [\"Speed\"] = \"Tempo\",\n [\"Spell description unavailable on this client.\"] = \"Die Zauberbeschreibung ist in diesem Client nicht verfügbar.\",\n [\"Spell icons\"] = \"Zauber-Icons\",\n [\"Spell icons and critical hits\"] = \"Zaubersymbole und kritische Treffer\",\n [\"Spells / rings / trinkets\"] = \"Zauber / Ringe / Schmuck\",\n [\"Split into 20 segments\"] = \"In 20 Abschnitte teilen\",\n [\"Square minimap (off: round)\"] = \"Quadratische Minikarte (aus: rund)\",\n [\"Standard\"] = \"Standard\",\n [\"Started with\"] = \"Zu Beginn\",\n [\"Starting luck unavailable\"] = \"Anfangsglück nicht verfügbar\",\n [\"Stat counter [WIP]\"] = \"Statistikzähler [IN ARBEIT]\",\n [\"Stat display\"] = \"Werteanzeige\",\n [\"Stats\"] = \"Werte\",\n [\"Stats category\"] = \"Wertekategorie\",\n [\"Stop sound\"] = \"Stop sound\",\n [\"Stretch across the whole screen\"] = \"Über den ganzen Bildschirm strecken\",\n [\"Successful revive\"] = \"Erfolgreiche Wiederbelebung\",\n [\"Support\"] = \"Support\",\n [\"Switch to horizontal\"] = \"Zu horizontal wechseln\",\n [\"Switch to vertical\"] = \"Zu vertikal wechseln\",\n [\"Taking the scenic route\"] = \"Taking the scenic route\",\n [\"Talent\"] = \"Talent\",\n [\"Target buffs/debuffs\"] = \"Ziel-Stärkungen/Schwächungen\",\n [\"Target buffs/debuffs position\"] = \"Position der Stärkungs- und Schwächungseffekte des Ziels\",\n [\"Target frame\"] = \"Zielfenster\",\n [\"Target frame look\"] = \"Zielfenster-Design\",\n [\"Target's buffs and debuffs\"] = \"Stärkungen und Schwächungen des Ziels\",\n [\"Teammate Death\"] = \"Teammate Death\",\n [\"Teammate death sound\"] = \"Todessound für Mitspieler\",\n [\"Teammate revive sound\"] = \"Wiederbelebungston für Mitspieler\",\n [\"Teammate revive sound (when you helped revive them)\"] = \"Ton bei Wiederbelebung eines Mitspielers (wenn du mitgeholfen hast)\",\n [\"That's everything. Press Finish to lock the UI. You can move anything again with Toggle UI Settings. Done closes the list.\"] = \"Das war alles. Wähle Abschließen, um die UI zu sperren. Mit den UI-Einstellungen kannst du jederzeit wieder Elemente verschieben. Fertig schließt die Liste.\",\n [\"The Price Is Right: losing horn\"] = \"The Price Is Right: Niederlagenfanfare\",\n [\"The bar shown while you bring a friend back.\"] = \"Die Leiste, die beim Wiederbeleben eines Freundes angezeigt wird.\",\n [\"The chat window, its tab and the box you type in move together.\"] = \"Chatfenster, Reiter und Eingabefeld werden gemeinsam verschoben.\",\n [\"The enemy the game has picked for you.\"] = \"Der Gegner, den das Spiel für dich ausgewählt hat.\",\n [\"The game's nearest Guardian lair flag\"] = \"Markierung des nächsten Wächterunterschlupfs\",\n [\"The game's own layout\"] = \"Das ursprüngliche Layout des Spiels\",\n [\"The game's own versions of these parts can't be moved. To move one, say yes below: Slim Suite swaps in its own movable copy. Each copy's other settings are in its menu: right-click it in Toggle UI Settings.\"] = \"Die Originalelemente des Spiels lassen sich nicht verschieben. Aktiviere eines unten, damit Slim Suite es durch eine bewegliche Version ersetzt. Weitere Optionen findest du per Rechtsklick darauf in den UI-Einstellungen.\",\n [\"The goal of clearing up chat is to see your friends' chat better in multiplayer.\"] = \"Das aufgeräumte Chatfenster hilft, die Nachrichten deiner Freunde im Mehrspielermodus besser zu sehen.\",\n [\"The local clock sits inside the minimap, and the minimap is Off, so the clock is hidden too.\"] = \"Die lokale Uhr sitzt in der Minikarte, und die Minikarte ist Aus, also ist auch die Uhr verborgen.\",\n [\"The meter. Its corner grip resizes it any time.\"] = \"Der Zähler. Über den Eckgriff kannst du jederzeit seine Größe ändern.\",\n [\"The minimap, with its pins.\"] = \"Die Minikarte mit Markierungen.\",\n [\"The movable Level Up button and its store toggle.\"] = \"Der verschiebbare Stufenaufstieg-Button und sein Speicher-Schalter.\",\n [\"The party frames are joined to the player frame, but the player frame is Off.\"] = \"Die Gruppenfenster hängen am Spielerfenster, aber das Spielerfenster ist Aus.\",\n [\"Thick\"] = \"Dick\",\n [\"Thin lines\"] = \"Schmale Linien\",\n [\"This view reports detected client and game hooks. Missing optional hooks do not necessarily prevent Slim Suite's core HUD features from working.\"] = \"Diese Ansicht zeigt erkannte Client- und Spiel-Hooks. Fehlende optionale Hooks verhindern nicht zwingend die grundlegenden HUD-Funktionen von Slim Suite.\",\n [\"Thorns\"] = \"Dornen\",\n [\"Tick: On. Empty: Off. D: Default (the game's own). Click a name with Advanced Options on to chain it.\"] = \"Haken: Ein. Leer: Aus. D: Standard (das Spieleigene). Mit „Erweiterte Optionen“ einen Namen anklicken, um ihn anzuhängen.\",\n [\"To Be Continued JoJo\"] = \"To Be Continued JoJo\",\n [\"Toggle UI Settings\"] = \"UI-Einstellungen umschalten\",\n [\"Toggle UI Settings (drag, resize and scale)\"] = \"UI-Einstellungen (verschieben, Größe und Skalierung)\",\n [\"Tooltip\"] = \"Kurzinfo\",\n [\"Tooltip width\"] = \"Tooltip-Breite\",\n [\"Top\"] = \"Oben\",\n [\"Tracking from\"] = \"Erfasst ab\",\n [\"Transparent minimap (round or square, no borders)\"] = \"Transparente Minikarte (rund oder eckig, ohne Rand)\",\n [\"Turn each element on, off, or back to the game's own.\"] = \"Schalte jedes Element ein, aus oder zurück auf das Spieleigene.\",\n [\"Turn off the game's nearest Guardian lair flag\"] = \"Die nächste Wächterhöhlen-Flagge des Spiels ausschalten\",\n [\"Turn the XP bar vertical\"] = \"EP-Leiste vertikal ausrichten\",\n [\"Turn the action bar vertical\"] = \"Aktionsleiste vertikal ausrichten\",\n [\"Turns off: Buffs on the target frame.\"] = \"Deaktiviert: Stärkungen am Zielfenster.\",\n [\"Turns off: Buffs/Debuffs on the player frame.\"] = \"Deaktiviert: Stärkungen/Schwächungen am Spielerfenster.\",\n [\"Turns off: Join the party yourself. Combines both frames and mirrors their positions at the same size.\"] = \"Deaktiviert: Der Gruppe selbst beitreten. Kombiniert beide Fenster und spiegelt ihre Positionen bei gleicher Größe.\",\n [\"Turns off: Join the party yourself. The player frame takes the target's look.\"] = \"Deaktiviert: Der Gruppe selbst beitreten. Das Spielerfenster übernimmt das Design des Ziels.\",\n [\"Turns off: your player frame (back when unticked) and Mirror Target. Your frame joins the party list.\"] = \"Deaktiviert: dein Spielerfenster (erscheint nach Abwählen wieder) und Ziel spiegeln. Dein Fenster wird Teil der Gruppenliste.\",\n [\"Type a word in the search box at the top (hide, clock, boss, size, party...) and every setting about it opens.\"] = \"Gib ein Wort ins Suchfeld oben ein (ausblenden, Uhr, Boss, Größe, Gruppe ...) und jede passende Einstellung öffnet sich.\",\n [\"UI\"] = \"Benutzeroberfläche\",\n [\"Unchain\"] = \"Lösen\",\n [\"Under or above the player frame takes you out of the party frames and makes the party movable.\"] = \"Unter oder über dem Spielerfenster wirst du aus den Gruppenfenstern entfernt und die Gruppe wird verschiebbar.\",\n [\"Under the player frame\"] = \"Unter dem Spielerfenster\",\n [\"Undo\"] = \"Rückgängig\",\n [\"Undo and Redo at the bottom of the settings (or /slim undo, /slim redo) step through your last 25 changes. /slim log shows every change.\"] = \"Rückgängig und Wiederholen unten in den Einstellungen (oder /slim undo, /slim redo) gehen deine letzten 25 Änderungen durch. /slim log zeigt jede Änderung.\",\n [\"Unit frame\"] = \"Einheitenfenster\",\n [\"Unofficial side objectives — no gameplay rewards.\"] = \"Unofficial side objectives — no gameplay rewards.\",\n [\"Updated enabled elements; Default and Disabled elements were left alone.\"] = \"Aktivierte Elemente wurden aktualisiert; Standard und deaktivierte Elemente blieben unverändert.\",\n [\"Use LEGO die instead of Baby Crying\"] = \"LEGO die statt Baby Crying verwenden\",\n [\"Use global soundtrack\"] = \"Use global soundtrack\",\n [\"Use modern Slim Suite enemy frames\"] = \"Moderne Slim-Suite-Gegnerfenster verwenden\",\n [\"Use this layout\"] = \"Dieses Layout verwenden\",\n [\"User Interface\"] = \"Benutzeroberfläche\",\n [\"Utility stats\"] = \"Weitere Werte\",\n [\"Vertical\"] = \"Vertikal\",\n [\"Vertical (off: horizontal)\"] = \"Vertikal (aus: horizontal)\",\n [\"Victory lap club\"] = \"Victory lap club\",\n [\"Victory sound\"] = \"Siegeston\",\n [\"Where event announcements appear.\"] = \"Position der Ereignismeldungen.\",\n [\"Where the big damage numbers appear\"] = \"Wo die großen Schadenszahlen erscheinen\",\n [\"Where tooltips appear, and how wide they are. Each one is as tall as its own text.\"] = \"Position und Breite der Tooltips. Jeder Tooltip passt sich der Höhe seines Textes an.\",\n [\"Whip Crack\"] = \"Peitschenknall\",\n [\"Width\"] = \"Breite\",\n [\"Win 10 observed runs.\"] = \"Win 10 observed runs.\",\n [\"Win an observed Heroic run.\"] = \"Win an observed Heroic run.\",\n [\"Window text size\"] = \"Textgröße der Fenster\",\n [\"World damage display\"] = \"Schaden in der Welt\",\n [\"Worn rings / trinkets row joins the build spell row\"] = \"Reihe getragener Ringe / Schmuckstücke hängt an der Zauberreihe\",\n [\"XP bar\"] = \"EP-Leiste\",\n [\"XP bonus\"] = \"EP-Bonus\",\n [\"Your Death\"] = \"Your Death\",\n [\"Your Death Sound\"] = \"Your Death Sound\",\n [\"Your buffs and debuffs. Below, stack them in a column and choose which way they grow. Attached to the target frame, they move and scale with it instead.\"] = \"Deine Stärkungen und Schwächungen. Unten kannst du sie stapeln und ihre Wachstumsrichtung wählen. Am Zielfenster bewegen und skalieren sie sich mit diesem.\",\n [\"Your build spells, with your worn jewelry joined under them.\"] = \"Deine Build-Zauber mit dem darunter angeordneten getragenen Schmuck.\",\n [\"Your experience bar. It can stand upright too (below).\"] = \"Deine Erfahrungsleiste. Sie kann auch senkrecht stehen (siehe unten).\",\n [\"Your friends' frames in co-op. They show now even if you're alone, so you can place them. Choose a column or a row, face plates or thin lines, and whether you join them.\"] = \"Fenster deiner Freunde im Koop. Sie werden auch allein angezeigt, damit du sie platzieren kannst. Wähle Spalte oder Zeile, Porträts oder dünne Linien und ob du der Gruppe beitrittst.\",\n [\"Your hero's frame: health, power and level. Drag the green handle to place it; its size and scale are below.\"] = \"Das Fenster deines Helden mit Gesundheit, Kraft und Stufe. Ziehe den grünen Griff zum Verschieben; Größe und Skalierung stellst du unten ein.\",\n [\"Your newest hits and heals, each with its spell icon. Crits stand out.\"] = \"Deine neuesten Treffer und Heilungen mit Zauber-Icon. Kritische Treffer heben sich ab.\",\n [\"Your read-only presets will appear here. Applying one creates your editable copy.\"] = \"Deine schreibgeschützten Vorlagen erscheinen hier. Beim Anwenden entsteht eine bearbeitbare Kopie.\",\n [\"Your real-world clock: 12/24-hour, its background and daylight saving are below.\"] = \"Deine lokale Uhr: 12/24-Stunden-Format, Hintergrund und Sommerzeit stellst du unten ein.\",\n [\"Your run's tally.\"] = \"Die Übersicht deiner Runde.\",\n [\"Your spells. Drag to place it; its size, and turning it upright, are below.\"] = \"Deine Zauber. Ziehe sie an die gewünschte Stelle; Größe und Ausrichtung stellst du unten ein.\",\n [\"Zelda: final four notes\"] = \"Zelda: letzte vier Noten\",\n [\"Zone and Heroic affixes\"] = \"Zone und heroische Affixe\",\n [\"all movable UI elements are back at their addon defaults.\"] = \"Alle verschiebbaren UI-Elemente stehen wieder an ihren Addon-Standardpositionen.\",\n [\"auto\"] = \"automatisch\",\n [\"build\"] = \"Build\",\n [\"cache\"] = \"Truhe\",\n [\"camera zoom is the game's own.\"] = \"Der Kamerazoom ist der des Spiels.\",\n [\"down\"] = \"unten\",\n [\"duck toy sound\"] = \"Quietscheenten-Sound\",\n [\"element positions are in the action log: /slimsuite log\"] = \"Elementpositionen stehen im Aktionslog: /slimsuite log\",\n [\"enter a profile name (char: names are reserved). \"] = \"Gib einen Profilnamen ein (Namen mit „char:“ sind reserviert). \",\n [\"frame sizes are in the action log: /slimsuite log\"] = \"Fenstergrößen stehen im Aktionslog: /slimsuite log\",\n [\"frames will move independently now.\"] = \"Fenster werden jetzt unabhängig voneinander verschoben.\",\n [\"interface\"] = \"Schnittstelle\",\n [\"movable elements are back at their original locations.\"] = \"Verschiebbare Elemente befinden sich wieder an ihrem ursprünglichen Platz.\",\n [\"nearby frames will latch together when you move them.\"] = \"Benachbarte Fenster rasten beim Verschieben zusammen ein.\",\n [\"next boss in\"] = \"Nächster Boss in\",\n [\"no words are hidden. /slim hide <words> hides chat lines with them.\"] = \"Keine Wörter ausgeblendet. /slim hide <Wörter> blendet Chatzeilen mit ihnen aus.\",\n [\"nothing to redo.\"] = \"Nichts zu wiederholen.\",\n [\"nothing to undo.\"] = \"Nichts rückgängig zu machen.\",\n [\"now  ->  with +10% luck\"] = \"jetzt  ->  mit +10% Glück\",\n [\"off\"] = \"aus\",\n [\"on\"] = \"ein\",\n [\"per-character:\"] = \"pro Charakter:\",\n [\"pillar man jojo\"] = \"pillar man jojo\",\n [\"profile deleted.\"] = \"Profil gelöscht.\",\n [\"screen\"] = \"Bildschirm\",\n [\"select a saved profile first.\"] = \"Wähle zuerst ein gespeichertes Profil.\",\n [\"template for\"] = \"für\",\n [\"that is a read-only default profile. Apply it to create a My Custom Profile copy first.\"] = \"Das ist ein schreibgeschütztes Standardprofil. Wende es an, um zuerst eine Kopie „Mein eigenes Profil“ zu erstellen.\",\n [\"that text is not a Slim Suite layout.\"] = \"Dieser Text ist kein Slim-Suite-Layout.\",\n [\"the UI is locked.\"] = \"Die UI ist gesperrt.\",\n [\"the frame label is off.\"] = \"Die Fensterbeschriftung ist ausgeschaltet.\",\n [\"the frame under your cursor is named next to it. /slimsuite mouse turns it off.\"] = \"Der Name des Fensters unter dem Cursor steht daneben. /slimsuite mouse schaltet dies aus.\",\n [\"the imported layout is now in use. Enter a profile name and import again to save it.\"] = \"Das importierte Layout ist jetzt aktiv. Gib einen Profilnamen ein und importiere erneut, um es zu speichern.\",\n [\"the imported profile bundle is saved. Select a profile to apply it.\"] = \"Das importierte Profilpaket ist gespeichert. Wähle ein Profil, um es anzuwenden.\",\n [\"the minimap button is back.\"] = \"Der Minikarten-Button ist wieder sichtbar.\",\n [\"the minimap button is hidden. /slimsuite minimap brings it back.\"] = \"Der Minikarten-Button ist ausgeblendet. /slimsuite minimap zeigt ihn wieder an.\",\n [\"the original size is not available yet; try again after the frame appears.\"] = \"Die Originalgröße ist noch nicht verfügbar. Versuche es erneut, sobald das Fenster erscheint.\",\n [\"the pasted layout is in use.\"] = \"Das eingefügte Layout wird verwendet.\",\n [\"the setup hit a problem and closed; your UI is back as it was. /slim errors shows what happened.\"] = \"Die Einrichtung hatte ein Problem und wurde geschlossen; deine Oberfläche ist wie vorher. /slim errors zeigt, was passiert ist.\",\n [\"there are no named profiles to export yet.\"] = \"Es gibt noch keine benannten Profile zum Exportieren.\",\