d\",\n [\"Stretch across the whole screen\"] = \"Estirar a lo ancho de toda la pantalla\",\n [\"Successful revive\"] = \"Reanimación exitosa\",\n [\"Support\"] = \"Ayuda\",\n [\"Switch to horizontal\"] = \"Cambiar a horizontal\",\n [\"Switch to vertical\"] = \"Cambiar a vertical\",\n [\"Taking the scenic route\"] = \"Taking the scenic route\",\n [\"Talent\"] = \"Talento\",\n [\"Target buffs/debuffs\"] = \"Beneficios/perjuicios del objetivo\",\n [\"Target buffs/debuffs position\"] = \"Posición de beneficios/perjuicios del objetivo\",\n [\"Target frame\"] = \"Marco del objetivo\",\n [\"Target frame look\"] = \"Apariencia del marco del objetivo\",\n [\"Target's buffs and debuffs\"] = \"Beneficios y perjuicios del objetivo\",\n [\"Teammate Death\"] = \"Teammate Death\",\n [\"Teammate death sound\"] = \"Sonido de muerte de compañeros\",\n [\"Teammate revive sound\"] = \"Sonido al revivir aliados\",\n [\"Teammate revive sound (when you helped revive them)\"] = \"Sonido al revivir a un compañero (si ayudaste a revivirlo)\",\n [\"That's everything. Press Finish to lock the UI. You can move anything again with Toggle UI Settings. Done closes the list.\"] = \"Eso es todo. Pulsa Finalizar para bloquear la interfaz. Puedes volver a mover cualquier elemento con Alternar ajustes de interfaz. Listo cierra la lista.\",\n [\"The Price Is Right: losing horn\"] = \"The Price Is Right: trompeta de derrota\",\n [\"The bar shown while you bring a friend back.\"] = \"La barra que aparece mientras revives a un amigo.\",\n [\"The chat window, its tab and the box you type in move together.\"] = \"La ventana de chat, su pestaña y el cuadro de escritura se mueven juntos.\",\n [\"The enemy the game has picked for you.\"] = \"El enemigo que el juego ha seleccionado para ti.\",\n [\"The game's nearest Guardian lair flag\"] = \"Marcador de guarida de Guardian más cercano\",\n [\"The game's own layout\"] = \"Diseño original del juego\",\n [\"The game's own versions of these parts can't be moved. To move one, say yes below: Slim Suite swaps in its own movable copy. Each copy's other settings are in its menu: right-click it in Toggle UI Settings.\"] = \"Las versiones originales del juego no se pueden mover. Activa una abajo para que Slim Suite la sustituya por una versión móvil. Sus opciones están en su menú: haz clic derecho en Alternar ajustes de interfaz.\",\n [\"The goal of clearing up chat is to see your friends' chat better in multiplayer.\"] = \"El objetivo de ordenar el chat es ver mejor los mensajes de tus amigos en multijugador.\",\n [\"The local clock sits inside the minimap, and the minimap is Off, so the clock is hidden too.\"] = \"El reloj local está dentro del minimapa y el minimapa está desactivado, así que el reloj también está oculto.\",\n [\"The meter. Its corner grip resizes it any time.\"] = \"El medidor. Puedes cambiar su tamaño arrastrando la esquina.\",\n [\"The minimap, with its pins.\"] = \"El minimapa y sus marcadores.\",\n [\"The movable Level Up button and its store toggle.\"] = \"El botón móvil Subir de nivel y su control de almacenamiento.\",\n [\"The party frames are joined to the player frame, but the player frame is Off.\"] = \"Los marcos de grupo están unidos al marco de jugador, pero el marco de jugador está desactivado.\",\n [\"Thick\"] = \"Gruesa\",\n [\"Thin lines\"] = \"Líneas finas\",\n [\"This view reports detected client and game hooks. Missing optional hooks do not necessarily prevent Slim Suite's core HUD features from working.\"] = \"Esta vista muestra las funciones detectadas del cliente y del juego. La ausencia de funciones opcionales no necesariamente impide el funcionamiento principal de Slim Suite.\",\n [\"Thorns\"] = \"Espinas\",\n [\"Tick: On. Empty: Off. D: Default (the game's own). Click a name with Advanced Options on to chain it.\"] = \"Marca: activado. Vacío: desactivado. D: predeterminado (el del juego). Con Opciones avanzadas, haz clic en un nombre para engancharlo.\",\n [\"To Be Continued JoJo\"] = \"To Be Continued JoJo\",\n [\"Toggle UI Settings\"] = \"Alternar ajustes de interfaz\",\n [\"Toggle UI Settings (drag, resize and scale)\"] = \"Alternar ajustes de interfaz (mover, cambiar tamaño y escala)\",\n [\"Tooltip\"] = \"Información emergente\",\n [\"Tooltip width\"] = \"Ancho de información emergente\",\n [\"Top\"] = \"Arriba\",\n [\"Tracking from\"] = \"Registro desde\",\n [\"Transparent minimap (round or square, no borders)\"] = \"Minimapa transparente (redondo o cuadrado, sin bordes)\",\n [\"Turn each element on, off, or back to the game's own.\"] = \"Activa, desactiva o devuelve cada elemento al del juego.\",\n [\"Turn off the game's nearest Guardian lair flag\"] = \"Desactivar la bandera de guarida de guardián más cercana del juego\",\n [\"Turn the XP bar vertical\"] = \"Poner la barra de experiencia en vertical\",\n [\"Turn the action bar vertical\"] = \"Poner la barra de acción en vertical\",\n [\"Turns off: Buffs on the target frame.\"] = \"Desactiva: Beneficios en el marco del objetivo.\",\n [\"Turns off: Buffs/Debuffs on the player frame.\"] = \"Desactiva: Beneficios/perjuicios en el marco del jugador.\",\n [\"Turns off: Join the party yourself. Combines both frames and mirrors their positions at the same size.\"] = \"Desactiva: Unirte al grupo. Combina ambos marcos y refleja sus posiciones con el mismo tamaño.\",\n [\"Turns off: Join the party yourself. The player frame takes the target's look.\"] = \"Desactiva: Unirte al grupo. El marco del jugador adopta la apariencia del objetivo.\",\n [\"Turns off: your player frame (back when unticked) and Mirror Target. Your frame joins the party list.\"] = \"Desactiva: el marco del jugador (vuelve al desmarcar) y Reflejar objetivo. Tu marco se une a la lista del grupo.\",\n [\"Type a word in the search box at the top (hide, clock, boss, size, party...) and every setting about it opens.\"] = \"Escribe una palabra en el cuadro de búsqueda de arriba (ocultar, reloj, jefe, tamaño, grupo...) y se abre cada ajuste relacionado.\",\n [\"UI\"] = \"Interfaz\",\n [\"Unchain\"] = \"Desenganchar\",\n [\"Under or above the player frame takes you out of the party frames and makes the party movable.\"] = \"Debajo o encima del marco del jugador te saca de los marcos del grupo y permite moverlos.\",\n [\"Under the player frame\"] = \"Debajo del marco del jugador\",\n [\"Undo\"] = \"Deshacer\",\n [\"Undo and Redo at the bottom of the settings (or /slim undo, /slim redo) step through your last 25 changes. /slim log shows every change.\"] = \"Deshacer y Rehacer, abajo en la configuración (o /slim undo, /slim redo), recorren tus últimos 25 cambios. /slim log muestra cada cambio.\",\n [\"Unit frame\"] = \"Marco de unidad\",\n [\"Unofficial side objectives — no gameplay rewards.\"] = \"Unofficial side objectives — no gameplay rewards.\",\n [\"Updated enabled elements; Default and Disabled elements were left alone.\"] = \"Se actualizaron los elementos activados; los predeterminados y desactivados no cambiaron.\",\n [\"Use LEGO die instead of Baby Crying\"] = \"Usar LEGO die en lugar de Baby Crying\",\n [\"Use global soundtrack\"] = \"Use global soundtrack\",\n [\"Use modern Slim Suite enemy frames\"] = \"Usar marcos enemigos modernos de Slim Suite\",\n [\"Use this layout\"] = \"Usar este diseño\",\n [\"User Interface\"] = \"Interfaz de usuario\",\n [\"Utility stats\"] = \"Estadísticas de utilidad\",\n [\"Vertical\"] = \"Vertical\",\n [\"Vertical (off: horizontal)\"] = \"Vertical (desactivado: horizontal)\",\n [\"Victory lap club\"] = \"Victory lap club\",\n [\"Victory sound\"] = \"Sonido de victoria\",\n [\"Where event announcements appear.\"] = \"Dónde aparecen los anuncios de eventos.\",\n [\"Where the big damage numbers appear\"] = \"Dónde aparecen los números de daño grandes\",\n [\"Where tooltips appear, and how wide they are. Each one is as tall as its own text.\"] = \"Dónde aparecen las descripciones emergentes y su anchura. Cada una se adapta a la altura de su texto.\",\n [\"Whip Crack\"] = \"Latigazo\",\n [\"Width\"] = \"Anchura\",\n [\"Win 10 observed runs.\"] = \"Win 10 observed runs.\",\n [\"Win an observed Heroic run.\"] = \"Win an observed Heroic run.\",\n [\"Window text size\"] = \"Tamaño del texto de las ventanas\",\n [\"World damage display\"] = \"Daño en el mundo\",\n [\"Worn rings / trinkets row joins the build spell row\"] = \"La fila de anillos / abalorios equipados se une a la fila de hechizos\",\n [\"XP bar\"] = \"Barra de experiencia\",\n [\"XP bonus\"] = \"Bonificación de experiencia\",\n [\"Your Death\"] = \"Your Death\",\n [\"Your Death Sound\"] = \"Your Death Sound\",\n [\"Your buffs and debuffs. Below, stack them in a column and choose which way they grow. Attached to the target frame, they move and scale with it instead.\"] = \"Tus beneficios y perjuicios. Abajo puedes apilarlos en una columna y elegir su dirección. Si se vinculan al marco del objetivo, se moverán y escalarán con él.\",\n [\"Your build spells, with your worn jewelry joined under them.\"] = \"Tus hechizos de la build, con las joyas equipadas debajo.\",\n [\"Your experience bar. It can stand upright too (below).\"] = \"Tu barra de experiencia. También puede ponerse en vertical (abajo).\",\n [\"Your friends' frames in co-op. They show now even if you're alone, so you can place them. Choose a column or a row, face plates or thin lines, and whether you join them.\"] = \"Marcos de tus amigos en cooperativo. Se muestran incluso si estás solo para que puedas colocarlos. Elige columna o fila, retratos o líneas finas, y si quieres unirte al grupo.\",\n [\"Your hero's frame: health, power and level. Drag the green handle to place it; its size and scale are below.\"] = \"Marco de tu héroe: salud, poder y nivel. Arrastra el control verde para colocarlo; abajo están su tamaño y escala.\",\n [\"Your newest hits and heals, each with its spell icon. Crits stand out.\"] = \"Tus golpes y sanaciones recientes, cada uno con su icono. Los críticos destacan.\",\n [\"Your read-only presets will appear here. Applying one creates your editable copy.\"] = \"Tus perfiles de solo lectura aparecerán aquí. Al aplicar uno se crea una copia editable.\",\n [\"Your real-world clock: 12/24-hour, its background and daylight saving are below.\"] = \"Tu reloj local: abajo puedes elegir formato de 12/24 horas, fondo y horario de verano.\",\n [\"Your run's tally.\"] = \"Resumen de tu partida.\",\n [\"Your spells. Drag to place it; its size, and turning it upright, are below.\"] = \"Tus hechizos. Arrástralos para colocarlos; abajo puedes cambiar su tamaño y orientación.\",\n [\"Zelda: final four notes\"] = \"Zelda: últimas cuatro notas\",\n [\"Zone and Heroic affixes\"] = \"Zona y afijos heroicos\",\n [\"all movable UI elements are back at their addon defaults.\"] = \"Todos los elementos móviles volvieron a sus posiciones predeterminadas.\",\n [\"auto\"] = \"automático\",\n [\"build\"] = \"compilación\",\n [\"cache\"] = \"cofre\",\n [\"camera zoom is the game's own.\"] = \"el zoom de cámara es el del juego.\",\n [\"down\"] = \"abajo\",\n [\"duck toy sound\"] = \"sonido de pato de juguete\",\n [\"element positions are in the action log: /slimsuite log\"] = \"las posiciones de los elementos están en el registro de acciones: /slimsuite log\",\n [\"enter a profile name (char: names are reserved). \"] = \"Escribe un nombre de perfil (los nombres con «char:» están reservados). \",\n [\"frame sizes are in the action log: /slimsuite log\"] = \"los tamaños de marco están en el registro de acciones: /slimsuite log\",\n [\"frames will move independently now.\"] = \"Los marcos ahora se moverán por separado.\",\n [\"interface\"] = \"interfaz\",\n [\"movable elements are back at their original locations.\"] = \"Los elementos móviles volvieron a sus ubicaciones originales.\",\n [\"nearby frames will latch together when you move them.\"] = \"Los marcos cercanos se ajustarán entre sí al moverlos.\",\n [\"next boss in\"] = \"siguiente jefe en\",\n [\"no words are hidden. /slim hide <words> hides chat lines with them.\"] = \"no hay palabras ocultas. /slim hide <palabras> oculta las líneas de chat que las contengan.\",\n [\"nothing to redo.\"] = \"nada que rehacer.\",\n [\"nothing to undo.\"] = \"nada que deshacer.\",\n [\"now  ->  with +10% luck\"] = \"ahora  ->  con +10% de suerte\",\n [\"off\"] = \"desactivado\",\n [\"on\"] = \"activado\",\n [\"per-character:\"] = \"por personaje:\",\n [\"pillar man jojo\"] = \"pillar man jojo\",\n [\"profile deleted.\"] = \"Perfil eliminado.\",\n [\"screen\"] = \"pantalla\",\n [\"select a saved profile first.\"] = \"Selecciona primero un perfil guardado.\",\n [\"template for\"] = \"para\",\n [\"that is a read-only default profile. Apply it to create a My Custom Profile copy first.\"] = \"Es un perfil predeterminado de solo lectura. Aplícalo para crear primero una copia «Mi perfil personalizado».\",\n [\"that text is not a Slim Suite layout.\"] = \"Ese texto no corresponde a un diseño de Slim Suite.\",\n [\"the UI is locked.\"] = \"La interfaz está bloqueada.\",\n [\"the frame label is off.\"] = \"La etiqueta del marco está desactivada.\",\n [\"the frame under your cursor is named next to it. /slimsuite mouse turns it off.\"] = \"El nombre del marco bajo el cursor aparece junto a él. /slimsuite mouse lo desactiva.\",\n [\"the imported layout is now in use. Enter a profile name and import again to save it.\"] = \"El diseño importado ya está en uso. Escribe un nombre de perfil e importa de nuevo para guardarlo.\",\n [\"the imported profile bundle is saved. Select a profile to apply it.\"] = \"El paquete de perfiles importado está guardado. Selecciona un perfil para aplicarlo.\",\n [\"the minimap button is back.\"] = \"El botón del minimapa está de vuelta.\",\n [\"the minimap button is hidden. /slimsuite minimap brings it back.\"] = \"El botón del minimapa está oculto. /slimsuite minimap lo muestra de nuevo.\",\n [\"the original size is not available yet; try again after the frame appears.\"] = \"El tamaño original aún no está disponible; inténtalo cuando aparezca el marco.\",\n [\"the pasted layout is in use.\"] = \"El diseño pegado está en uso.\",\n [\"the setup hit a problem and closed; your UI is back as it was. /slim errors shows what happened.\"] = \"la configuración tuvo un problema y se cerró; tu interfaz está como antes. /slim errors muestra lo ocurrido.\",\n [\"there are no named profiles to export yet.\"] = \"Aún no hay perfiles con nombre para exportar.\",\n [\"this client cannot change the minimap's shape.\"] = \"Este cliente no puede cambiar la forma del minimapa.\",\n [\"up\"] = \"arriba\",\n [\"usage: /slim camera save <name> [yards]. Names start with a letter.\"] = \"uso: /slim camera save <nombre> [metros]. Los nombres empiezan con una letra.\",\n};"
SS.LOCALE_SOURCE.frFR = "return {\n [\"   ...and Guardians and lairs before they're pulled\"] = \"   ...et les gardiens et repaires avant le combat\",\n [\"   Show their name\"] = \"   Afficher leur nom\",\n [\"   Show their raid icon\"] = \"   Afficher leur icône de raid\",\n [\"%s is On but at 0%% opacity, so it can't be seen.\"] = \"%s est activé mais à 0%% d'opacité, donc invisible.\",\n [\"(Right click element to change settings)\"] = \"(Clic droit sur un élément pour modifier ses réglages)\",\n [\"+%.2f pts\"] = \"+%.2f pts\",\n [\"+1 hour\"] = \"+1 heure\",\n [\"-1 hour\"] = \"-1 heure\",\n [\"/slim camera <yards>, +, -, <preset>, save <name> [yards], delete <name>, list, on, off.\"] = \"/slim camera <mètres>, +, -, <préréglage>, save <nom> [mètres], delete <nom>, list, on, off.\",\n [\"/slim camera: the distance now. /slim camera <yards>, +, -, <preset>, save <name> [yards], delete <name>, list, on, off.\"] = \"/slim camera : la distance actuelle. /slim camera <mètres>, +, -, <préréglage>, save <nom> [mètres], delete <nom>, list, on, off.\",\n [\"/slim demo: Demo Mode on or off.  /slim levelup: Slim Suite's Level Up button or the game's own.\"] = \"/slim demo : mode démo activé ou non.  /slim levelup : le bouton de niveau de Slim Suite ou celui du jeu.\",\n [\"/slim hide <words>, /slim unhide <words>, /slim hide: chat lines with those words.\"] = \"/slim hide <mots>, /slim unhide <mots>, /slim hide : lignes de discussion contenant ces mots.\",\n [\"/slim hud: recommended positions for this display.\"] = \"/slim hud : positions recommandées pour cet écran.\",\n [\"/slim layout save <name>, load <name>, delete <name>, list. The window shares a layout as text.\"] = \"/slim layout save <nom>, load <nom>, delete <nom>, list. La fenêtre partage une disposition sous forme de texte.\",\n [\"/slim layout: manage named profiles and import/export layouts.  /slim layout save <name>, load <name>, delete <name>, list.\"] = \"/slim layout : gérer les profils nommés et importer/exporter des dispositions.  /slim layout save <nom>, load <nom>, delete <nom>, list.\",\n [\"/slim minimap: the gear button.  /slim errors: the error log.  /slim mouse: names the frame under the cursor.\"] = \"/slim minimap : le bouton d'engrenage.  /slim errors : le journal d'erreurs.  /slim mouse : nomme le cadre sous le curseur.\",\n [\"/slim positions: write where every element sits (position, size, scale) to the action log.\"] = \"/slim positions : écrit où se trouve chaque élément (position, taille, échelle) dans le journal d'actions.\",\n [\"/slim reset places puts every element back where it started; /slim reset all also resets sizes, scales and layouts.\"] = \"/slim reset places remet chaque élément à sa place d'origine ; /slim reset all réinitialise aussi tailles, échelles et dispositions.\",\n [\"/slim reset places, /slim reset all: back to where everything started.\"] = \"/slim reset places, /slim reset all : tout revient là où il a commencé.\",\n [\"/slim: the settings window.  /slim edit: move and size the UI (/slim lock when done).  /slim setup: the guided setup.\"] = \"/slim : la fenêtre des paramètres.  /slim edit : déplacer et redimensionner l'interface (/slim lock une fois fini).  /slim setup : la configuration guidée.\",\n [\"24-hour time\"] = \"Format 24 heures\",\n [\"3D portrait\"] = \"Portrait 3D\",\n [\"3D portrait on the new-school frame\"] = \"Portrait 3D sur le cadre moderne\",\n [\"A Swiss-army knife of useful tools and UI controls.\"] = \"Une boîte à outils polyvalente pour l’interface et le jeu.\",\n [\"A million little problems\"] = \"A million little problems\",\n [\"A stat the game sends that Slim Suite has no description for yet.\"] = \"Une statistique envoyée par le jeu que Slim Suite ne décrit pas encore.\",\n [\"Above the player frame\"] = \"Au-dessus du cadre du joueur\",\n [\"Above the target frame\"] = \"Au-dessus du cadre de la cible\",\n [\"Absorb amounts\"] = \"Montants absorbés\",\n [\"Accessibility\"] = \"Accessibilité\",\n [\"According to the records\"] = \"According to the records\",\n [\"Action bar\"] = \"Barre d’action\",\n [\"Active buffs\"] = \"Améliorations actives\",\n [\"Add your racial as a 7th button\"] = \"Ajouter votre racial comme septième bouton\",\n [\"Addon interface:\"] = \"Interface de l’extension :\",\n [\"Addon version\"] = \"Version de l’extension\",\n [\"Addons\"] = \"Extensions\",\n [\"Advanced Options\"] = \"Options avancées\",\n [\"Aethus creations\"] = \"Créations d'Aethus\",\n [\"All elements start disabled on a new install. Enable one to show and move it; Default restores the game's original element. Right-click its name for settings. Your Default profiles will appear beside this list.\"] = \"Sur une nouvelle installation, tous les éléments sont désactivés. Activez-en un pour l’afficher et le déplacer ; Par défaut restaure l’élément d’origine du jeu. Faites un clic droit sur son nom pour ouvrir ses réglages. Vos profils par défaut apparaîtront à côté de cette liste.\",\n [\"All set\"] = \"Terminé\",\n [\"Also write the numbers in the combat log\"] = \"Écrire aussi les chiffres dans le journal de combat\",\n [\"Amulets\"] = \"Amulettes\",\n [\"Announcements\"] = \"Annonces\",\n [\"Anywhere\"] = \"N’importe où\",\n [\"Applied %s preset for %sx%s. Repositioned %d enabled elements; Default and Disabled elements stayed in place. Save a profile first if you want an easy way back.\"] = \"Préréglage %s appliqué pour %sx%s. %d éléments activés ont été repositionnés ; les éléments par défaut et désactivés n’ont pas bougé. Enregistrez un profil avant pour revenir facilement en arrière.\",\n [\"Applied the\"] = \"Préréglage appliqué :\",\n [\"Apply recommended positions\"] = \"Appliquer les positions recommandées\",\n [\"Apply selected\"] = \"Appliquer la sélection\",\n [\"Applying a read-only preset creates your editable copy.\"] = \"Appliquer un préréglage en lecture seule crée votre copie modifiable.\",\n [\"Area\"] = \"Zone\",\n [\"At the start of the run\