w caches on the map\"] = \"Afficher les caches sur la carte\",\n [\"Show caches on the minimap\"] = \"Afficher les caches sur la minicarte\",\n [\"Show character faces\"] = \"Afficher les visages des personnages\",\n [\"Show chests\"] = \"Afficher les coffres\",\n [\"Show debuffs on the bars\"] = \"Afficher les affaiblissements sur les barres\",\n [\"Show distance in yards\"] = \"Afficher la distance en mètres\",\n [\"Show empty buttons\"] = \"Afficher les boutons vides\",\n [\"Show every button at all times, even empty ones\"] = \"Afficher tous les boutons en permanence, même vides\",\n [\"Show every element above the level-up and new-item cards (each element can still be set on its own)\"] = \"Afficher tous les éléments au-dessus des fenêtres de niveau et de nouvel objet (chaque élément peut aussi être réglé seul)\",\n [\"Show feature\"] = \"Afficher la fonction\",\n [\"Show green absorb amounts on player and party frames (when the client exposes them)\"] = \"Afficher les valeurs d’absorption en vert sur les cadres du joueur et du groupe (si le client les fournit)\",\n [\"Show healing numbers\"] = \"Afficher les chiffres de soins\",\n [\"Show heals\"] = \"Afficher les soins\",\n [\"Show lairs\"] = \"Afficher les repaires\",\n [\"Show lairs and their refill timer\"] = \"Afficher les repaires et leur recharge\",\n [\"Show lairs on the minimap, with their 3:00 refill timer\"] = \"Afficher les repaires sur la minicarte avec leur recharge de 3:00\",\n [\"Show location and difficulty\"] = \"Afficher le lieu et la difficulté\",\n [\"Show map name and difficulty\"] = \"Afficher le nom de la carte et la difficulté\",\n [\"Show my layout\"] = \"Afficher ma disposition\",\n [\"Show native enemy nameplates\"] = \"Afficher les barres de nom ennemies natives\",\n [\"Show over the level-up / new-item cards\"] = \"Afficher au-dessus des fenêtres de niveau et de nouvel objet\",\n [\"Show the game's nearest Guardian lair flag on minimap\"] = \"Afficher le repère du repaire de gardi