d\"] = \"Velocidade\",\n [\"Spell description unavailable on this client.\"] = \"A descrição do feitiço não está disponível neste cliente.\",\n [\"Spell icons\"] = \"Ícones de feitiços\",\n [\"Spell icons and critical hits\"] = \"Ícones de feitiços e acertos críticos\",\n [\"Spells / rings / trinkets\"] = \"Feitiços / anéis / berloques\",\n [\"Split into 20 segments\"] = \"Dividir em 20 segmentos\",\n [\"Square minimap (off: round)\"] = \"Minimapa quadrado (desligado: redondo)\",\n [\"Standard\"] = \"Padrão\",\n [\"Started with\"] = \"No início\",\n [\"Starting luck unavailable\"] = \"Sorte inicial indisponível\",\n [\"Stat counter [WIP]\"] = \"Contador de atributos [WIP]\",\n [\"Stat display\"] = \"Exibição de atributos\",\n [\"Stats\"] = \"Atributos\",\n [\"Stats category\"] = \"Categoria de atributos\",\n [\"Stop sound\"] = \"Stop sound\",\n [\"Stretch across the whole screen\"] = \"Esticar pela largura da tela\",\n [\"Successful revive\"] = \"Revive bem-sucedido\",\n [\"Support\"] = \"Suporte\",\n [\"Switch to horizontal\"] = \"Mudar para horizontal\",\n [\"Switch to vertical\"] = \"Mudar para vertical\",\n [\"Taking the scenic route\"] = \"Taking the scenic route\",\n [\"Talent\"] = \"Talento\",\n [\"Target buffs/debuffs\"] = \"Benefícios/Penalidades do alvo\",\n [\"Target buffs/debuffs position\"] = \"Posição dos benefícios/penalidades do alvo\",\n [\"Target frame\"] = \"Quadro do alvo\",\n [\"Target frame look\"] = \"Aparência do quadro do alvo\",\n [\"Target's buffs and debuffs\"] = \"Benefícios e penalidades do alvo\",\n [\"Teammate Death\"] = \"Teammate Death\",\n [\"Teammate death sound\"] = \"Som de morte dos aliados\",\n [\"Teammate revive sound\"] = \"Som de reviver aliado\",\n [\"Teammate revive sound (when you helped revive them)\"] = \"Som ao reviver um colega (quando você ajudou a revivê-lo)\",\n [\"That's everything. Press Finish to lock the UI. You can move anything again with Toggle UI Settings. Done closes the list.\"] = \"Tudo pronto. Pressione Finalizar para travar a interface. Use Alternar opções da interface para movê-la novamente. Pronto fecha a lista.\",\n [\"The Price Is Right: losing horn\"] = \"The Price Is Right: trombeta de derrota\",\n [\"The bar shown while you bring a friend back.\"] = \"A barra mostrada ao reanimar um aliado.\",\n [\"The chat window, its tab and the box you type in move together.\"] = \"A janela de bate-papo, sua aba e a caixa de texto se movem juntas.\",\n [\"The enemy the game has picked for you.\"] = \"O inimigo que o jogo escolheu para você.\",\n [\"The game's nearest Guardian lair flag\"] = \"Bandeira do covil de Guardião mais próximo\",\n [\"The game's own layout\"] = \"Layout original do jogo\",\n [\"The game's own versions of these parts can't be moved. To move one, say yes below: Slim Suite swaps in its own movable copy. Each copy's other settings are in its menu: right-click it in Toggle UI Settings.\"] = \"As versões originais destes elementos não podem ser movidas. Para mover, ative abaixo: Slim Suite usa sua própria cópia móvel. Clique direito no elemento em Alternar opções da interface para outras opções.\",\n [\"The goal of clearing up chat is to see your friends' chat better in multiplayer.\"] = \"Limpar o bate-papo ajuda a enxergar as mensagens dos amigos no multijogador.\",\n [\"The local clock sits inside the minimap, and the minimap is Off, so the clock is hidden too.\"] = \"O relógio local fica dentro do minimapa, e o minimapa está desligado, então o relógio também fica oculto.\",\n [\"The meter. Its corner grip resizes it any time.\"] = \"O medidor. Arraste seu canto para redimensioná-lo a qualquer momento.\",\n [\"The minimap, with its pins.\"] = \"O minimapa com seus marcadores.\",\n [\"The movable Level Up button and its store toggle.\"] = \"O botão móvel de nível e sua opção de guardar níveis.\",\n [\"The party frames are joined to the player frame, but the player frame is Off.\"] = \"Os quadros de grupo estão presos ao quadro de jogador, mas o quadro de jogador está desligado.\",\n [\"Thick\"] = \"Espesso\",\n [\"Thin lines\"] = \"Linhas finas\",\n [\"This view reports detected client and game hooks. Missing optional hooks do not necessarily prevent Slim Suite's core HUD features from working.\"] = \"Esta tela mostra as integrações detectadas no cliente e no jogo. Funções opcionais ausentes não impedem necessariamente o HUD principal de funcionar.\",\n [\"Thorns\"] = \"Espinhos\",\n [\"Tick: On. Empty: Off. D: Default (the game's own). Click a name with Advanced Options on to chain it.\"] = \"Marcado: ligado. Vazio: desligado. D: padrão (o do jogo). Com Opções avançadas, clique em um nome para prendê-lo.\",\n [\"To Be Continued JoJo\"] = \"To Be Continued JoJo\",\n [\"Toggle UI Settings\"] = \"Alternar opções da interface\",\n [\"Toggle UI Settings (drag, resize and scale)\"] = \"Alternar opções da interface (arrastar, tamanho e escala)\",\n [\"Tooltip\"] = \"Dica\",\n [\"Tooltip width\"] = \"Largura das dicas\",\n [\"Top\"] = \"Em cima\",\n [\"Tracking from\"] = \"Registro desde\",\n [\"Transparent minimap (round or square, no borders)\"] = \"Minimapa transparente (redondo ou quadrado, sem bordas)\",\n [\"Turn each element on, off, or back to the game's own.\"] = \"Ligue, desligue ou devolva cada elemento ao do jogo.\",\n [\"Turn off the game's nearest Guardian lair flag\"] = \"Desligar a bandeira do covil de guardião mais próximo do jogo\",\n [\"Turn the XP bar vertical\"] = \"Colocar barra de XP na vertical\",\n [\"Turn the action bar vertical\"] = \"Colocar barra de ações na vertical\",\n [\"Turns off: Buffs on the target frame.\"] = \"Desativa: benefícios no quadro do alvo.\",\n [\"Turns off: Buffs/Debuffs on the player frame.\"] = \"Desativa: benefícios/penalidades no quadro do jogador.\",\n [\"Turns off: Join the party yourself. Combines both frames and mirrors their positions at the same size.\"] = \"Desativa: incluir você no grupo. Combina os quadros e espelha suas posições no mesmo tamanho.\",\n [\"Turns off: Join the party yourself. The player frame takes the target's look.\"] = \"Desativa: incluir você no grupo. O quadro do jogador usa a aparência do alvo.\",\n [\"Turns off: your player frame (back when unticked) and Mirror Target. Your frame joins the party list.\"] = \"Desativa: seu quadro do jogador (volta ao desmarcar) e Espelhar alvo. Seu quadro entra na lista do grupo.\",\n [\"Type a word in the search box at the top (hide, clock, boss, size, party...) and every setting about it opens.\"] = \"Digite uma palavra na busca no topo (ocultar, relógio, chefe, tamanho, grupo...) e cada ajuste relacionado se abre.\",\n [\"UI\"] = \"Interface\",\n [\"Unchain\"] = \"Desprender\",\n [\"Under or above the player frame takes you out of the party frames and makes the party movable.\"] = \"Colocar acima ou abaixo do jogador remove você do grupo e permite mover seus quadros.\",\n [\"Under the player frame\"] = \"Abaixo do quadro do jogador\",\n [\"Undo\"] = \"Desfazer\",\n [\"Undo and Redo at the bottom of the settings (or /slim undo, /slim redo) step through your last 25 changes. /slim log shows every change.\"] = \"Desfazer e Refazer, no rodapé das configurações (ou /slim undo, /slim redo), percorrem suas últimas 25 alterações. /slim log mostra cada alteração.\",\n [\"Unit frame\"] = \"Quadro da unidade\",\n [\"Unofficial side objectives — no gameplay rewards.\"] = \"Unofficial side objectives — no gameplay rewards.\",\n [\"Updated enabled elements; Default and Disabled elements were left alone.\"] = \"Elementos ativos atualizados; Padrão e Desativados não foram alterados.\",\n [\"Use LEGO die instead of Baby Crying\"] = \"Usar morte LEGO em vez de bebê chorando\",\n [\"Use global soundtrack\"] = \"Use global soundtrack\",\n [\"Use modern Slim Suite enemy frames\"] = \"Usar quadros inimigos modernos do Slim Suite\",\n [\"Use this layout\"] = \"Usar este layout\",\n [\"User Interface\"] = \"Interface do usuário\",\n [\"Utility stats\"] = \"Atributos utilitários\",\n